----- ROOT ID FUNCTION FOR: [Communities].[ParentCommunityKey]
------------------------------------------------------------
IF OBJECT_ID('[higher_logic_thrive_community].[fnCommunitiesParentCommunityKey_GetRootID]', 'IF') IS NOT NULL
    DROP FUNCTION [higher_logic_thrive_community].[fnCommunitiesParentCommunityKey_GetRootID];
