CREATE FUNCTION [higher_logic_thrive_community].[fnDiscussionPostsParentDiscussionPostKey_GetRootID]
(
    @RecordID nvarchar(450),
    @ParentID nvarchar(450)
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [DiscussionPostKey],
            [ParentDiscussionPostKey],
            [DiscussionPostKey] AS [RootParentID],
            0 AS [Depth]
        FROM
            [higher_logic_thrive_community].[DiscussionPosts]
        WHERE
            [DiscussionPostKey] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[DiscussionPostKey],
            c.[ParentDiscussionPostKey],
            c.[DiscussionPostKey] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [higher_logic_thrive_community].[DiscussionPosts] c
        INNER JOIN
            CTE_RootParent p ON c.[DiscussionPostKey] = p.[ParentDiscussionPostKey]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [ParentDiscussionPostKey] IS NULL
    ORDER BY
        [RootParentID]
);
GO

